# Terraform Circular Dependency + count/for_each Fix

## Root Causes

1. **Circular Dependency**: The output `db_endpoint` references `aws_db_instance.main[0].endpoint` unconditionally, but with `count = length(var.envs)`, if the list is empty or the logic changes, this breaks.

2. **count Misuse**: `count = length(var.envs)` creates *one DB instance per environment in the list*, but the architecture should deploy *one DB per environment workspace/tfvars file*. The output then hardcodes `[0]`, creating unclear intent and fragile state.

3. **Deletion Protection Weakness**: Hard-coded to `false` even for prod.

4. **Incomplete Spec**: Missing S3, IAM, EKS, and HTTPS resources.

---

## Fixed Solution

### `main.tf`

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# ─────────────────────────────────────────
# RDS PostgreSQL Instance (no count/for_each)
# ─────────────────────────────────────────
# Single resource per workspace/tfvars — environment selection is external (workspace or -var-file)
resource "aws_db_instance" "main" {
  identifier            = "${var.env}-db"
  allocated_storage     = var.db_allocated_storage
  engine                = "postgres"
  engine_version        = "16.1"
  instance_class        = var.instance_class
  db_name               = var.db_name
  username              = var.db_user
  password              = var.db_password
  multi_az              = var.env == "prod" ? true : false
  storage_encrypted     = true
  publicly_accessible   = false
  skip_final_snapshot   = false
  final_snapshot_identifier = "${var.env}-db-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"
  deletion_protection   = var.env == "prod" ? true : false
  backup_retention_period = var.env == "prod" ? 30 : 7

  tags = {
    Environment = var.env
  }
}

# ─────────────────────────────────────────
# S3 Bucket (application assets)
# ─────────────────────────────────────────
resource "aws_s3_bucket" "assets" {
  bucket = "${var.env}-app-assets-${data.aws_caller_identity.current.account_id}"

  tags = {
    Environment = var.env
  }
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Conditional: prod only — cross-region replication to us-west-2
resource "aws_s3_bucket_replication_configuration" "assets" {
  count      = var.env == "prod" ? 1 : 0
  depends_on = [aws_s3_bucket_versioning.assets]

  bucket = aws_s3_bucket.assets.id

  role = aws_iam_role.s3_replication[0].arn

  rule {
    status = "Enabled"

    destination {
      bucket       = "arn:aws:s3:::${var.env}-app-assets-${data.aws_caller_identity.current.account_id}-west"
      storage_class = "STANDARD"
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  count = var.env == "prod" ? 1 : 0

  name = "${var.env}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# ─────────────────────────────────────────
# EKS Cluster
# ─────────────────────────────────────────
resource "aws_eks_cluster" "main" {
  name            = "${var.env}-eks"
  role_arn        = aws_iam_role.eks_cluster.arn
  version         = "1.29"

  vpc_config {
    subnet_ids = aws_subnet.main[*].id
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy
  ]

  tags = {
    Environment = var.env
  }
}

resource "aws_eks_node_group" "main" {
  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "${var.env}-nodes"
  node_role_arn   = aws_iam_role.eks_nodes.arn
  subnet_ids      = aws_subnet.main[*].id

  scaling_config {
    desired_size = var.eks_desired_nodes
    max_size     = var.eks_max_nodes
    min_size     = 1
  }

  instance_types = [var.eks_instance_type]

  depends_on = [
    aws_iam_role_policy_attachment.eks_node_policy
  ]

  tags = {
    Environment = var.env
  }
}

# EKS IAM roles
resource "aws_iam_role" "eks_cluster" {
  name = "${var.env}-eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role" "eks_nodes" {
  name = "${var.env}-eks-nodes-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_nodes.name
}

# ─────────────────────────────────────────
# IAM Service Account
# ─────────────────────────────────────────
resource "aws_iam_user" "app_service_account" {
  name = "${var.env}-app-service-account"

  tags = {
    Environment = var.env
  }
}

resource "aws_iam_role" "app_service_role" {
  name = "${var.env}-app-service-role"

  assume_role_policy = var.env == "prod" ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_user.app_service_account.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  }) : jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Least-privilege policy for prod only
resource "aws_iam_role_policy" "app_service_policy" {
  count  = var.env == "prod" ? 1 : 0
  name   = "${var.env}-app-service-policy"
  role   = aws_iam_role.app_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.assets.arn,
          "${aws_s3_bucket.assets.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "rds-db:connect"
        ]
        Resource = aws_db_instance.main.arn
      }
    ]
  })
}

# ─────────────────────────────────────────
# Networking (minimal for EKS)
# ─────────────────────────────────────────
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Environment = var.env
  }
}

resource "aws_subnet" "main" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index % 2]
  map_public_ip_on_launch = true

  tags = {
    Environment = var.env
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ─────────────────────────────────────────
# ALB (internal for dev, CloudFront for prod)
# ─────────────────────────────────────────
resource "aws_lb" "internal" {
  count           = var.env == "dev" ? 1 : 0
  name            = "${var.env}-alb"
  internal        = true
  load_balancer_type = "application"
  subnets         = aws_subnet.main[*].id

  tags = {
    Environment = var.env
  }
}

resource "aws_lb_listener" "http_to_https" {
  count           = var.env == "dev" ? 1 : 0
  load_balancer_arn = aws_lb.internal[0].arn
  port            = "80"
  protocol        = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }
}

# ─────────────────────────────────────────
# CloudFront (prod only)
# ─────────────────────────────────────────
resource "aws_cloudfront_distribution" "prod" {
  count           = var.env == "prod" ? 1 : 0
  enabled         = true

  origin {
    domain_name = aws_s3_bucket.assets.bucket_regional_domain_name
    origin_id   = "S3"
  }

  default_cache_behavior {
    cache_policy_id        = "658327ea-f89d-4fab-a63d-7e88639e58f6" # Managed-CachingOptimized
    compress               = true
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = "S3"
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Environment = var.env
  }
}

# ─────────────────────────────────────────
# Secrets (stored externally, referenced via SOPS or parameter store)
# ─────────────────────────────────────────
resource "aws_secretsmanager_secret" "db_connection" {
  name                    = "${var.env}/db-connection-string"
  recovery_window_in_days = 7

  tags = {
    Environment = var.env
  }
}

resource "aws_secretsmanager_secret_version" "db_connection" {
  secret_id = aws_secretsmanager_secret.db_connection.id
  secret_string = jsonencode({
    username = var.db_user
    password = var.db_password
    engine   = "postgres"
    host     = aws_db_instance.main.endpoint
    port     = 5432
    dbname   = var.db_name
  })
}

# ─────────────────────────────────────────
# Data source for current AWS account
# ─────────────────────────────────────────
data "aws_caller_identity" "current" {}

# ─────────────────────────────────────────
# OUTPUTS (no circular references)
# ─────────────────────────────────────────
output "db_endpoint" {
  description = "RDS instance endpoint"
  value       = aws_db_instance.main.endpoint
  depends_on  = [aws_db_instance.main]
}

output "s3_bucket_name" {
  description = "Application assets S3 bucket name"
  value       = aws_s3_bucket.assets.id
}

output "eks_cluster_name" {
  description = "EKS cluster name"
  value       = aws_eks_cluster.main.name
}

output "eks_cluster_endpoint" {
  description = "EKS cluster API endpoint"
  value       = aws_eks_cluster.main.endpoint
}

output "cloudfront_domain_name" {
  description = "CloudFront distribution domain (prod only)"
  value       = var.env == "prod" ? aws_cloudfront_distribution.prod[0].domain_name : null
}

output "alb_dns_name" {
  description = "ALB DNS name (dev only)"
  value       = var.env == "dev" ? aws_lb.internal[0].dns_name : null
}
```

### `variables.tf`

```hcl
variable "region" {
  type        = string
  description = "AWS region"
  default     = "us-east-1"
}

variable "env" {
  type        = string
  description = "Environment name (dev or prod)"
  default     = "dev"

  validation {
    condition     = contains(["dev", "prod"], var.env)
    error_message = "env must be 'dev' or 'prod'."
  }
}

variable "instance_class" {
  type        = string
  description = "RDS instance class"
  default     = "db.t3.medium"
}

variable "db_allocated_storage" {
  type        = number
  description = "RDS allocated storage (GB)"
  default     = 20
}

variable "db_name" {
  type        = string
  description = "PostgreSQL database name"
  default     = "appdb"
}

variable "db_user" {
  type        = string
  description = "PostgreSQL master username"
  default     = "app_user"
}

variable "db_password" {
  type        = string
  sensitive   = true
  description = "PostgreSQL master password (use SOPS or environment variable)"
}

variable "eks_instance_type" {
  type        = string
  description = "EKS node instance type"
  default     = "t3.medium"
}

variable "eks_desired_nodes" {
  type        = number
  description = "Desired number of EKS nodes"
  default     = 2
}

variable "eks_max_nodes" {
  type        = number
  description = "Maximum number of EKS nodes"
  default     = 4
}

variable "vpc_cidr" {
  type        = string
  description = "VPC CIDR block"
  default     = "10.0.0.0/16"
}
```

### `dev.tfvars`

```hcl
env                 = "dev"
region              = "us-east-1"
instance_class      = "db.t3.micro"
eks_instance_type   = "t3.medium"
eks_desired_nodes   = 2
eks_max_nodes       = 2
```

### `prod.tfvars`

```hcl
env                 = "prod"
region              = "us-east-1"
instance_class      = "db.t3.medium"
eks_instance_type   = "t3.large"
eks_desired_nodes   = 4
eks_max_nodes       = 6
```

---

## Key Fixes

| Issue | Fix |
|-------|-----|
| **Circular dependency** | Removed `count`. Single DB resource per workspace; output depends_on ensures correct ordering. |
| **count/for_each mismatch** | Replaced `count = length(var.envs)` with environment-aware conditionals (`var.env == "prod"`). Per-environment deployment via separate tfvars files. |
| **Deletion protection** | Conditional: `var.env == "prod" ? true : false` |
| **Missing resources** | Added S3 (versioning + encryption + replication for prod), EKS, IAM, ALB, CloudFront, Secrets Manager. |
| **Secrets** | AWS Secrets Manager (encrypted at rest); DB password via `-var-file` or SOPS. |
| **Principle of least privilege** | IAM policy for prod uses explicit resource ARNs; dev has minimal setup. |

## Deployment

```bash
# Dev
terraform apply -var-file=dev.tfvars -var="db_password=$(sops decrypt .sops.env.json | jq -r .db_password)"

# Prod
terraform apply -var-file=prod.tfvars -var="db_password=$(sops decrypt .sops.env.json | jq -r .db_password)"
```
